  each('[data-field]',e=>e.oninput=()=>o[e.dataset.field]=e.type==='number'?Number(e.value):e.value);
  if(query('[data-type]'))query('[data-type]').onchange=e=>{const next=e.target.value,has=Object.values(bomMap(o)).flat().length||(o.productCodes||[]).length||(o.machineIds||[]).length||(o.ipqcAssignments||[]).length;if((['entry','exit'].includes(next)&&has)||(next!=='machine'&&(o.machineIds||[]).length)){m.dialog.querySelector('.pe-form-error').textContent=t('此類型變更會隱藏現有產品／BOM／機器／IPQC 關聯。請先在原分頁明確處理；原資料已保留。','Đổi loại sẽ ẩn liên kết hiện có. Hãy xử lý ở các tab gốc; dữ liệu được giữ.');e.target.value=kind(o);return;}o.editorType=next;o.mode=next==='machine'?'machine':'human';drawTabs();repaint();};
  function chooseProduct(code,on){o.productCodes=on?[...new Set([...(o.productCodes||[]),code])]:(o.productCodes||[]).filter(x=>x!==code);if(!on){o.bomSelections=copy(bomMap(o));delete o.bomSelections[code];o.bomItems=Object.values(o.bomSelections).flat();if(o.bomProductCode===code)o.bomProductCode='';}}
  each('[data-product]',e=>e.onchange=()=>chooseProduct(e.dataset.product,e.checked));each('[data-remove-product]',e=>e.onclick=()=>{chooseProduct(e.dataset.removeProduct,false);repaint();});if(query('[data-product-search]'))query('[data-product-search]').oninput=e=>each('.pe-product-list label',r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));
  function selectBom(product,key,on){const source=rootBom(product).filter(r=>codeKey(bomReferenceKey(r))===key);if(on&&(source.length!==1||owners(product,key,o.id).length))return;o.bomSelections=copy(bomMap(o));const codes=(o.bomSelections[product]||[]).filter(c=>codeKey(c)!==key);if(on)codes.push(bomReferenceKey(source[0]));o.bomSelections[product]=codes;o.bomItems=Object.values(o.bomSelections).flat();}
  each('[data-bom-common]',e=>{e.indeterminate=e.dataset.partial==='true';e.onchange=()=>{let count=0;for(const product of o.productCodes||[]){const own=rootBom(product).filter(r=>codeKey(r.itemCode)===e.dataset.bomCommon);if(own.length===1&&!owners(product,e.dataset.bomCommon,o.id).length){selectBom(product,e.dataset.bomCommon,e.checked);count++;}}repaint();query('.pe-bom-result').textContent=t(`已更新 ${count} 個可用產品，仍需套用。`,`Đã cập nhật ${count} sản phẩm; cần áp dụng.`);};});
  each('[data-bom-cell]',e=>e.onchange=()=>{selectBom(e.dataset.bomProduct,e.dataset.bomCell,e.checked);const open=[...p.querySelectorAll('details')].map(d=>d.open);repaint();p.querySelectorAll('details').forEach((d,i)=>d.open=open[i]);});each('[data-bom-clear]',e=>e.onclick=()=>{for(const product of Object.keys(bomMap(o)))selectBom(product,e.dataset.bomClear,false);repaint();});if(query('[data-bom-search]')){const search=query('[data-bom-search]');search.value=m.bomSearch||'';search.oninput=()=>{m.bomSearch=search.value;each('.pe-bom-row',r=>r.hidden=!r.textContent.toLowerCase().includes(search.value.toLowerCase()));};search.oninput();}
  each('[data-machine-photo]',e=>e.onclick=()=>{const row=m.machineRows[Number(e.dataset.machinePhoto)],machine=row.equipment||row;album((machine.mediaItems||[]).filter(x=>x.src&&!x.type?.startsWith('video')),machine.name||machine.number);});
