  const product=m.tab==='product-work'?m.product:'',steps=()=>product?(o.productInstructionSteps||={})[product]||=(( [] )):(o.instructionSteps||=[]),media=()=>product?operationProductMediaItems(o,product):operationWorkMediaItems(o),setMedia=items=>{if(product)(o.productMediaItems||={})[product]=items;else{ o.mediaItems=items;o.media=items[0]?.src||null;o.mediaName=items[0]?.name||'';o.mediaType=items[0]?.type||'';}};
  if(query('[data-work-note]'))query('[data-work-note]').oninput=e=>{if(product)(o.productInstructions||={})[product]=e.target.value;else o.instructions=e.target.value;};for(const name of ['name','text','standard'])each('[data-step-'+name+']',e=>e.oninput=()=>{const index=Number(e.dataset['step'+name[0].toUpperCase()+name.slice(1)]);const list=steps(),isNew=!list[index];list[index]||={name:'',text:'',standard:''};list[index][name]=e.value;if(isNew){const items=query('[data-work-step-list]');if(items){items.innerHTML=workItemsMarkup(list,index);each('[data-select-step]',e=>e.onclick=()=>{m.workSelection[product||'common']=Number(e.dataset.selectStep);repaint();});}const empty=query('[data-work-empty]'),actions=query('[data-work-step-actions]'),heading=query('[data-work-selection]');if(empty)empty.hidden=true;if(actions)actions.hidden=false;if(heading)heading.textContent=t('編輯項目','Sửa mục')+' '+(index+1);}if(name==='name'){const label=query('[data-select-step="'+index+'"] span');if(label)label.textContent=e.value||t('未命名項目','Mục chưa đặt tên');}});
  each('[data-select-step]',e=>e.onclick=()=>{m.workSelection[product||'common']=Number(e.dataset.selectStep);repaint();});
  for(const [name,delta]of [['up',-1],['down',1]])each('[data-step-'+name+']',e=>e.onclick=()=>{const list=steps(),from=Number(e.dataset[name==='up'?'stepUp':'stepDown']),to=from+delta;if(to<0||to>=list.length)return;[list[from],list[to]]=[list[to],list[from]];m.workSelection[product||'common']=to;repaint();});
